from datetime import datetime, timedelta

class Scheduler:
    def __init__(self) -> None:
        self.appointments = []
        self.patient_appointments = {}
        self.appointment_id_counter = 0

    def book(self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime, note: str = "") -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start < now:
            raise ValueError("Appointment cannot start before the current time")

        if patient in self.patient_appointments and self.patient_appointments[patient]['end'] > now:
            raise ValueError("Patient already has an upcoming appointment")

        for appointment in self.appointments:
            if appointment['doctor'] == doctor and (start < appointment['end'] and end > appointment['start']):
                raise ValueError("Appointment overlaps with another appointment of the same doctor")

        self.appointment_id_counter += 1
        self.appointments.append({
            'id': self.appointment_id_counter,
            'patient': patient,
            'doctor': doctor,
            'start': start,
            'end': end,
            'cancelled': False,
            'note': note
        })
        self.patient_appointments[patient] = {
            'id': self.appointment_id_counter,
            'start': start,
            'end': end
        }

        return self.appointment_id_counter

    def cancel(self, appointment_id: int, now: datetime) -> None:
        for appointment in self.appointments:
            if appointment['id'] == appointment_id:
                if appointment['start'] - now < timedelta(hours=24) and not appointment['cancelled']:
                    appointment['cancelled'] = True
                else:
                    self.appointments.remove(appointment)
                    for patient, patient_appointment in self.patient_appointments.items():
                        if patient_appointment['id'] == appointment_id:
                            del self.patient_appointments[patient]
                return
        raise ValueError("Appointment not found")

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        for appointment in self.appointments:
            if appointment['doctor'] == doctor and (start < appointment['end'] and end > appointment['start']) and not appointment['cancelled']:
                return False
        return True

    def appointments_of(self, doctor: str) -> list[dict]:
        """Returns the doctor's appointments sorted by start time, each with keys id, patient, start and end."""
        return sorted([{
            'id': appointment['id'],
            'patient': appointment['patient'],
            'start': appointment['start'],
            'end': appointment['end']
        } for appointment in self.appointments if appointment['doctor'] == doctor and not appointment['cancelled']], key=lambda x: x['start'])

    def note(self, appointment_id: int) -> str:
        for appointment in self.appointments:
            if appointment['id'] == appointment_id:
                return appointment['note']
        raise ValueError("Appointment not found")
